<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Document</title>
    
</head>
<body>
    <style>
        p{
          text-align: justify; 
          font-size: 30px; 
          font-weight: bold;"  
        }
        table {
              width: 100%;
              height: 10px;
            }
    </style>
    <div class="container">
        <div class="row">
          <!--Logo principal index -->
          <div class="col-xs-12  col-md-4">
            <img src='data:image/jpeg;base64,'/>
          </div>
          <hr>
          <div class="col-xs-12  col-md-8">
            <h2 style="text-align: center; font-size: 30px; font-weight: bold;">
              Ficha de Remisi&oacute;n de Proceso por Competencia o en Segunda Instancia
            </h2>
          </div>
          
        </div>
        <div class="row">
           <table class="default">
          <tr>
            <td>
                 <p>
                    Motivo de la Remisi&oacute;n:
                </p>
            </td>
            <td>
                  <p>
                  {{$m_remision}}  
                </p>
            </td>
        
          </tr>
          <tr>
            <td>
                 <p>
                     Especialidad a quien va dirigido:
                </p>
            </td>
            <td>
                  <p>
                  {{$especialidad}}   
                </p>
            </td>
        
          </tr>
          <tr>
            <td>
                 <p>
                      Despacho que remite:
                </p>
            </td>
            <td>
                  <p>
                  {{$despacho_remite}}  
                </p>
            </td>
        
          </tr>
          <tr>
            <td>
                 <p>
                      Radicaci&oacute;n del proceso:
                </p>
            </td>
            <td>
                  <p>
                  {{$numero_radicado_proceso}} 
                </p>
            </td>
        
          </tr>
          <tr>
            <td>
                 <p>
                      Grupo de reparto:
                </p>
            </td>
            <td>
                  <p>
                  {{$gr_reparto}}  
                </p>
            </td>
        
          </tr>
          <tr>
            <td>
                 <p>
                     Conocimiento previo:
                </p>
            </td>
            <td>
                  <p>
                  {{$concocimiento_pre}} 
                </p>
            </td>
        
          </tr>
          <tr>
            <td>
                 <p>
                     Demandante (s):
                </p>
            </td>
            <td>
                  <p>
                   {{$demandante}} 
                </p>
            </td>
        
          </tr>
           <tr>
            <td>
                 <p>
                     Demandando (s):
                </p>
            </td>
            <td>
                  <p>
                   {{$demandado}}  
                </p>
            </td>
        
          </tr>
        </table> 
        </div>
     
        <br>
        <br>
        <hr>
        <table class="default">
          <tr>
            <td>
                <img style="height: 120px;text-align: right;" src='data:image/png;base64,'/>
            </td>
        
            <td><a style="font-size: 30px;" href="https://www.disajcali.gov.co/">www.disajcali.gov.co</a> </td>
        
            <td>
                <img style="height: 120px;" src='data:image/png;base64,'/>    
            </td>
        
          </tr>
        </table>
    </div>
</body>
</html>